import{_ as t,o,c as i,a2 as r}from"./chunks/framework.D3GK3dQI.js";const m=JSON.parse('{"title":"ADR-005: Security Hardening","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/005-security.md","filePath":"adrs/005-security.md"}'),n={name:"adrs/005-security.md"};function s(a,e,l,c,d,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-005-security-hardening" tabindex="-1">ADR-005: Security Hardening <a class="header-anchor" href="#adr-005-security-hardening" aria-label="Permalink to &quot;ADR-005: Security Hardening&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-06<br><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>As a Kubernetes infrastructure component with <code>ClusterRole</code> read permissions, this exporter requires stringent security measures to prevent privilege escalation, resource exhaustion, and unauthorized access.</p><h2 id="decisions-implemented" tabindex="-1">Decisions Implemented <a class="header-anchor" href="#decisions-implemented" aria-label="Permalink to &quot;Decisions Implemented&quot;">​</a></h2><ol><li><p><strong>HTTP Server Hardening (Slowloris Protection):</strong></p><ul><li>The default Go <code>http.Server</code> is vulnerable to Slowloris attacks where a client opens a connection but sends data very slowly, exhausting the server&#39;s connection pool.</li><li>We configured explicit timeouts: <code>ReadTimeout</code> (5s), <code>ReadHeaderTimeout</code> (2s), <code>WriteTimeout</code> (10s), and <code>IdleTimeout</code> (120s) to forcefully drop slow or dead connections.</li></ul></li><li><p><strong>Minimal Distroless Container:</strong></p><ul><li>The application is containerized using a multi-stage Docker build.</li><li>The runtime image is <code>gcr.io/distroless/static:nonroot</code>. It contains no shell or package manager, reducing the runtime attack surface.</li><li>The application runs entirely as <code>nonroot</code> (UID 65532).</li><li>Builder and runtime images are pinned to immutable manifest-list digests; readable tags remain alongside the digests for maintenance context.</li></ul></li><li><p><strong>Kubernetes Runtime Hardening:</strong></p><ul><li>The default chart sets <code>runAsNonRoot</code>, UID/GID 65532, a read-only root filesystem, disabled privilege escalation, dropped capabilities, and the <code>RuntimeDefault</code> seccomp profile.</li></ul></li><li><p><strong>Readiness Probe Integrity:</strong></p><ul><li>The <code>/readyz</code> endpoint ensures the Kubernetes API cache (<code>controller-runtime</code> informer) is fully synchronized before returning 200 OK. This prevents routing traffic to an empty instance.</li></ul></li><li><p><strong>Principle of Least Privilege (RBAC):</strong></p><ul><li>The Helm chart grants read-only access to <code>Gateway</code>, <code>HTTPRoute</code>, <code>ReferenceGrant</code>, <code>Namespace</code>, and <code>Service</code> resources required for relationship resolution.</li></ul></li><li><p><strong>NetworkPolicy Baseline:</strong></p><ul><li>A <code>NetworkPolicy</code> limits inbound connections to port 8080. Egress is currently unrestricted because API-server and optional OTEL destinations vary by cluster; operators should narrow it for their environment.</li></ul></li></ol><h2 id="future-recommendations-what-else-needs-securing" tabindex="-1">Future Recommendations (What else needs securing?) <a class="header-anchor" href="#future-recommendations-what-else-needs-securing" aria-label="Permalink to &quot;Future Recommendations (What else needs securing?)&quot;">​</a></h2><p>To achieve a &quot;Zero Trust&quot; production state, the following should be implemented in the cluster environment:</p><ol><li><strong>mTLS (Mutual TLS):</strong><ul><li>Wrap the pod in a Service Mesh (e.g., Istio or Linkerd) to encrypt traffic between Prometheus and this exporter, or configure Prometheus to use TLS client certificates.</li></ul></li></ol>',9)])])}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
